44	/**
45	 * Mostly used as a facade for all Petclinic controllers
46	 * Also a placeholder for @Transactional and @Cacheable annotations
47	 *
48	 * @author Michael Isvy
49	 * @author Vitaliy Fedoriv
50	 */
51	@Service
52	public class ClinicServiceImpl implements ClinicService {
53	
54	    /** Dedicated audit trail logger for owner-lifecycle side-effects. */
55	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
56	
57	    private final PetRepository petRepository;
58	    private final VetRepository vetRepository;
59	    private final OwnerRepository ownerRepository;
60	    private final VisitRepository visitRepository;
61	    private final SpecialtyRepository specialtyRepository;
62	    private final PetTypeRepository petTypeRepository;
63	
64	    public ClinicServiceImpl(
65	        PetRepository petRepository,
66	        VetRepository vetRepository,
67	        OwnerRepository ownerRepository,
68	        VisitRepository visitRepository,
69	        SpecialtyRepository specialtyRepository,
70	        PetTypeRepository petTypeRepository) {
71	        this.petRepository = petRepository;
72	        this.vetRepository = vetRepository;
73	        this.ownerRepository = ownerRepository;
74	        this.visitRepository = visitRepository;
75	        this.specialtyRepository = specialtyRepository;
76	        this.petTypeRepository = petTypeRepository;
77	    }
78	
79	    @Override
80	    @Transactional(readOnly = true)
81	    public Collection<Pet> findAllPets() throws DataAccessException {
82	        return petRepository.findAll();
83	    }
84	
85	    @Override
86	    @Transactional(readOnly = true)
87	    public Page<Pet> findPets(Pageable pageable) throws DataAccessException {
88	        return petRepository.findAll(pageable);
89	    }
90	
91	    @Override
92	    @Transactional
93	    public void deletePet(Pet pet) throws DataAccessException {
94	        petRepository.delete(pet);
95	    }
96	
97	    @Override
98	    @Transactional(readOnly = true)
99	    public Visit findVisitById(int visitId) throws DataAccessException {
100	        return findEntityById(() -> visitRepository.findById(visitId));
101	    }
102	
103	    @Override
104	    @Transactional(readOnly = true)
105	    public Collection<Visit> findAllVisits() throws DataAccessException {
106	        return visitRepository.findAll();
107	    }
108	
109	    @Override
110	    @Transactional
111	    public void deleteVisit(Visit visit) throws DataAccessException {
112	        visitRepository.delete(visit);
113	    }
114	
115	    @Override
116	    @Transactional(readOnly = true)
117	    public Vet findVetById(int id) throws DataAccessException {
118	        return findEntityById(() -> vetRepository.findById(id));
119	    }
120	
121	    @Override
122	    @Transactional(readOnly = true)
123	    public Collection<Vet> findAllVets() throws DataAccessException {
124	        return vetRepository.findAll();
125	    }
126	
127	    @Override
128	    @Transactional
129	    public void saveVet(Vet vet) throws DataAccessException {
130	        vetRepository.save(vet);
131	    }
132	
133	    @Override
134	    @Transactional
135	    public void deleteVet(Vet vet) throws DataAccessException {
136	        vetRepository.delete(vet);
137	    }
138	
139	    @Override
140	    @Transactional(readOnly = true)
141	    public Collection<Owner> findAllOwners() throws DataAccessException {
142	        Collection<Owner> owners = ownerRepository.findAll();
143	        populateHouseholdSizes(owners);
144	        return owners;
145	    }
146	
147	    @Override
148	    @Transactional(readOnly = true)
149	    public Page<Owner> findOwners(String lastName, Pageable pageable) throws DataAccessException {
150	        Page<Owner> owners = (lastName != null)
151	            ? ownerRepository.findByLastName(lastName, pageable)
152	            : ownerRepository.findAll(pageable);
153	        populateHouseholdSizes(owners.getContent());
154	        return owners;
155	    }
156	
157	    @Override
158	    @Transactional
159	    public void deleteOwner(Owner owner) throws DataAccessException {
160	        ownerRepository.delete(owner);
161	    }
162	
163	    @Override
164	    @Transactional(readOnly = true)
165	    public PetType findPetTypeById(int petTypeId) {
166	        return findEntityById(() -> petTypeRepository.findById(petTypeId));
167	    }
168	
169	    @Override
170	    @Transactional(readOnly = true)
171	    public Collection<PetType> findAllPetTypes() throws DataAccessException {
172	        return petTypeRepository.findAll();
173	    }
174	
175	    @Override
176	    @Transactional
177	    public void savePetType(PetType petType) throws DataAccessException {
178	        petTypeRepository.save(petType);
179	    }
180	
181	    @Override
182	    @Transactional
183	    public void deletePetType(PetType petType) throws DataAccessException {
184	        petTypeRepository.delete(petType);
185	    }
186	
187	    @Override
188	    @Transactional(readOnly = true)
189	    public Specialty findSpecialtyById(int specialtyId) {
190	        return findEntityById(() -> specialtyRepository.findById(specialtyId));
191	    }
192	
193	    @Override
194	    @Transactional(readOnly = true)
195	    public Collection<Specialty> findAllSpecialties() throws DataAccessException {
196	        return specialtyRepository.findAll();
197	    }
198	
199	    @Override
200	    @Transactional
201	    public void saveSpecialty(Specialty specialty) throws DataAccessException {
202	        specialtyRepository.save(specialty);
203	    }
204	
205	    @Override
206	    @Transactional
207	    public void deleteSpecialty(Specialty specialty) throws DataAccessException {
208	        specialtyRepository.delete(specialty);
209	    }
210	
211	    @Override
212	    @Transactional(readOnly = true)
213	    public Collection<PetType> findPetTypes() throws DataAccessException {
214	        return petRepository.findPetTypes();
215	    }
216	
217	    @Override
218	    @Transactional(readOnly = true)
219	    public Owner findOwnerById(int id) throws DataAccessException {
220	        Owner owner = findEntityById(() -> ownerRepository.findById(id));
221	        populateHouseholdSize(owner);
222	        return owner;
223	    }
224	
225	    @Override
226	    @Transactional(readOnly = true)
227	    public Pet findPetById(int id) throws DataAccessException {
228	        return findEntityById(() -> petRepository.findById(id));
229	    }
230	
231	    @Override
232	    @Transactional
233	    public void savePet(Pet pet) throws DataAccessException {
234	        pet.setType(findPetTypeById(pet.getType().getId()));
235	        petRepository.save(pet);
236	    }
237	
238	    @Override
239	    @Transactional
240	    public void saveVisit(Visit visit) throws DataAccessException {
241	        visitRepository.save(visit);
242	
243	    }
244	
245	    @Override
246	    @Transactional(readOnly = true)
247	    public Collection<Vet> findVets() throws DataAccessException {
248	        return vetRepository.findAll();
249	    }
250	
251	    /** Region -> inclusive 4-digit postcode range {low, high}. */
252	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
253	        "NSW", new int[] {2000, 2099},
254	        "VIC", new int[] {3000, 3099},
255	        "QLD", new int[] {4000, 4099});
256	
257	    /**
258	     * Rejects saving {@code owner} when it carries a postcode that is out of range for its city's
259	     * region. The postcode is optional: a {@code null} postcode is left untouched. When present it
260	     * is assumed to already be four digits (enforced by request validation); if the owner's city has
261	     * a known region (see {@link Region}), the postcode must fall within that region's range
262	     * ({@link #REGION_POSTCODES}). A city with no known region accepts any 4-digit postcode.
263	     *
264	     * @throws InvalidPostcodeException if the postcode is out of range for the city's region
265	     */
266	    private void assertPostcodeValid(Owner owner) {
267	        String postcode = owner.getPostcode();
268	        if (postcode == null) {
269	            return;
270	        }
271	        String region = Region.forCity(owner.getCity());
272	        int[] range = region == null ? null : REGION_POSTCODES.get(region);
273	        if (range == null) {
274	            return;
275	        }
276	        int value = Integer.parseInt(postcode);
277	        if (value < range[0] || value > range[1]) {
278	            throw new InvalidPostcodeException(postcode, owner.getCity(), region);
279	        }
280	    }
281	
282	    @Override
283	    @Transactional
284	    public void saveOwner(Owner owner) throws DataAccessException {
285	        assertPostcodeValid(owner);
286	        if (owner.getTelephone() != null) {
287	            owner.setTelephone(normalizeTelephone(owner.getTelephone()));
288	        }
289	        if (owner.getEmail() != null) {
290	            owner.setEmail(normalizeEmail(owner.getEmail()));
291	        }
292	        if (owner.getAddress() != null) {
293	            owner.setAddress(normalizeAddress(owner.getAddress()));
294	        }
295	        LocalDate effectiveDate = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
296	        owner.setRegistrationDate(rollToBusinessDay(effectiveDate));
297	        if (owner.getCustomerCode() == null) {
298	            owner.setCustomerCode(generateCustomerCode(owner));
299	        }
300	        boolean creating = owner.isNew();
301	        if (creating) {
302	            owner.setNamesakeCount(countNamesakes(owner));
303	            assertDailyCapacity(owner);
304	            assertCityCapacity(owner);
305	        }
306	        List<Owner> household = findHouseholdMembers(owner);
307	        assignHousehold(owner, household);
308	        assertIdentityUnique(owner);
309	        ownerRepository.save(owner);
310	        populateHouseholdSize(owner);
311	        if (creating) {
312	            AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
313	                owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
314	                owner.getMembershipLevel());
315	        }
316	    }
317	
318	    /**
319	     * Build a {@code customerCode} formatted {@code '<CITY3>-<LAST3>-<NNNN>'} where CITY3 is the
320	     * upper-cased first three letters of the owner's city, LAST3 the upper-cased first three
321	     * letters of {@code lastName}, and NNNN is a per-city 4-digit zero-padded sequence equal to
322	     * one more than the number of owners already in that city.
323	     */
324	    private String generateCustomerCode(Owner owner) {
325	        String cityPrefix = prefix3(owner.getCity());
326	        String lastNamePrefix = prefix3(owner.getLastName());
327	        long sequence = countOwnersInCity(owner.getCity()) + 1L;
328	        return String.format("%s-%s-%04d", cityPrefix, lastNamePrefix, sequence);
329	    }
330	
331	    private static String prefix3(String value) {
332	        return value.substring(0, Math.min(3, value.length())).toUpperCase(Locale.ROOT);
333	    }
334	
335	    /** Maximum number of owners permitted in a single city. */
336	    private static final long CITY_OWNER_LIMIT = 50L;
337	
338	    /**
339	     * Rejects creating {@code owner} when its city already contains {@link #CITY_OWNER_LIMIT} or
340	     * more owners, so no city can grow beyond the capacity limit.
341	     *
342	     * @throws CityOwnerLimitException if the owner's city is already at capacity
343	     */
344	    private void assertCityCapacity(Owner owner) {
345	        if (owner.getCity() == null) {
346	            return;
347	        }
348	        if (countOwnersInCity(owner.getCity()) >= CITY_OWNER_LIMIT) {
349	            throw new CityOwnerLimitException(owner.getCity(), CITY_OWNER_LIMIT);
350	        }
351	    }
352	
353	    /**
354	     * Rolls {@code date} forward to the next business day when it falls on a weekend: a Saturday or
355	     * Sunday becomes the following Monday. Business days (Monday to Friday) are returned unchanged.
356	     */
357	    private static LocalDate rollToBusinessDay(LocalDate date) {
358	        switch (date.getDayOfWeek()) {
359	            case SATURDAY:
360	                return date.plusDays(2);
361	            case SUNDAY:
362	                return date.plusDays(1);
363	            default:
364	                return date;
365	        }
366	    }
367	
368	    /** Maximum number of owners permitted to be registered on a single day. */
369	    private static final long DAILY_OWNER_LIMIT = 100L;
370	
371	    /** More than this many owners registered on a single day raises the bulk-signup warning. */
372	    private static final long BULK_SIGNUP_THRESHOLD = 80L;
373	
374	    /**
375	     * Reports whether more than {@link #BULK_SIGNUP_THRESHOLD} owners have already been registered
376	     * today, reusing the same daily accumulation as the per-day create limit ({@link
377	     * #assertDailyCapacity}).
378	     */
379	    @Override
380	    @Transactional(readOnly = true)
381	    public boolean isBulkSignupWarningActive() throws DataAccessException {
382	        return countOwnersRegisteredOn(LocalDate.now()) > BULK_SIGNUP_THRESHOLD;
383	    }
384	
385	    /**
386	     * Rejects creating {@code owner} when its {@code registrationDate} (defaulted to today for a new
387	     * owner) already has {@link #DAILY_OWNER_LIMIT} or more owners registered, so no more than that
388	     * many owners can be created on any single day.
389	     *
390	     * @throws DailyOwnerLimitException if the owner's registration day is already at capacity
391	     */
392	    private void assertDailyCapacity(Owner owner) {
393	        LocalDate date = owner.getRegistrationDate();
394	        if (date == null) {
395	            return;
396	        }
397	        if (countOwnersRegisteredOn(date) >= DAILY_OWNER_LIMIT) {
398	            throw new DailyOwnerLimitException(date, DAILY_OWNER_LIMIT);
399	        }
400	    }
401	
402	    private long countOwnersRegisteredOn(LocalDate date) {
403	        return ownerRepository.findAll().stream()
404	                .filter(existing -> date.equals(existing.getRegistrationDate()))
405	                .count();
406	    }
407	
408	    private long countOwnersInCity(String city) {
409	        String normalized = normalizeHouseholdValue(city);
410	        return ownerRepository.findAll().stream()
411	                .filter(existing -> normalized.equals(normalizeHouseholdValue(existing.getCity())))
412	                .count();
413	    }
414	
415	    /**
416	     * Counts the existing owners that share both {@code firstName} and {@code lastName} with the
417	     * given new {@code owner}, compared case-insensitively (with incidental whitespace collapsed).
418	     * The owner being created is not itself persisted yet, so the result is the number of namesakes
419	     * that already existed before this create.
420	     */
421	    private int countNamesakes(Owner owner) {
422	        String firstName = normalizeHouseholdValue(owner.getFirstName());
423	        String lastName = normalizeHouseholdValue(owner.getLastName());
424	        int count = 0;
425	        for (Owner existing : ownerRepository.findAll()) {
426	            if (!existing.getId().equals(owner.getId())
427	                    && firstName.equals(normalizeHouseholdValue(existing.getFirstName()))
428	                    && lastName.equals(normalizeHouseholdValue(existing.getLastName()))) {
429	                count++;
430	            }
431	        }
432	        return count;
433	    }
434	
435	    private static String normalizeEmail(String email) {
436	        return email == null ? null : email.toLowerCase(Locale.ROOT);
437	    }
438	
439	    /** Common street-type abbreviations expanded during address normalization. */
440	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
441	        "ST", "STREET",
442	        "RD", "ROAD",
443	        "AVE", "AVENUE");
444	
445	    /**
446	     * Canonicalizes a postal address: trims and collapses runs of whitespace into a single space,
447	     * upper-cases, and expands common street-type abbreviations (ST->STREET, RD->ROAD, AVE->AVENUE)
448	     * as whole words. Returns {@code null} for a {@code null} input and an empty string when the
449	     * address is blank once whitespace is stripped, so the required-field check sees the normalized
450	     * form.
451	     */
452	    private static String normalizeAddress(String address) {
453	        if (address == null) {
454	            return null;
455	        }
456	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
457	        if (collapsed.isEmpty()) {
458	            return "";
459	        }
460	        String[] tokens = collapsed.split(" ");
461	        StringBuilder sb = new StringBuilder(collapsed.length());
462	        for (int i = 0; i < tokens.length; i++) {
463	            if (i > 0) {
464	                sb.append(' ');
465	            }
466	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
467	        }
468	        return sb.toString();
469	    }
470	
471	    private static String normalizeTelephone(String telephone) {
472	        return telephone == null ? null : E164Telephone.toE164(telephone);
473	    }
474	
475	    /**
476	     * Rejects saving {@code owner} when its whole {@link Owner#getIdentityKey() identity key} equals
477	     * that of another owner. This single check consolidates the former separate telephone, email and
478	     * household duplicate rules: because the normalized telephone is part of the key, two members of
479	     * the same household (same {@code householdId}) with different telephones have different keys and
480	     * are both allowed — only an exact full-key match is a duplicate.
481	     *
482	     * @throws DuplicateIdentityException if another owner already has the same identity key
483	     */
484	    private void assertIdentityUnique(Owner owner) {
485	        String identityKey = owner.getIdentityKey();
486	        for (Owner existing : ownerRepository.findAll()) {
487	            if (!existing.getId().equals(owner.getId()) && identityKey.equals(existing.getIdentityKey())) {
488	                throw new DuplicateIdentityException(identityKey);
489	            }
490	        }
491	    }
492	
493	    /**
494	     * Returns the existing owners that share both {@code lastName} (compared case-insensitively with
495	     * collapsed whitespace) and the normalized {@code address} with a new {@code owner} — i.e. the
496	     * members of the household it would join. Returns an empty list for an update to an existing
497	     * owner or when either household value is blank, so household rules only apply to genuine new
498	     * members.
499	     */
500	    private List<Owner> findHouseholdMembers(Owner owner) {
501	        if (!owner.isNew()) {
502	            return List.of();
503	        }
504	        String lastName = normalizeHouseholdValue(owner.getLastName());
505	        String address = normalizeHouseholdAddress(owner.getAddress());
506	        if (lastName.isEmpty() || address.isEmpty()) {
507	            return List.of();
508	        }
509	        List<Owner> household = new ArrayList<>();
510	        for (Owner existing : ownerRepository.findAll()) {
511	            if (!existing.getId().equals(owner.getId())
512	                    && lastName.equals(normalizeHouseholdValue(existing.getLastName()))
513	                    && address.equals(normalizeHouseholdAddress(existing.getAddress()))) {
514	                household.add(existing);
515	            }
516	        }
517	        return household;
518	    }
519	
520	    /**
521	     * Assigns household membership when {@code owner} joins a non-empty {@code household}: the new
522	     * owner and every matching existing member that lacks one are given the same stable
523	     * {@code householdId}, and any updated existing members are persisted. No-op when the household
524	     * is empty.
525	     */
526	    private void assignHousehold(Owner owner, List<Owner> household) {
527	        if (household.isEmpty()) {
528	            return;
529	        }
530	        String householdId = resolveHouseholdId(owner, household);
531	        owner.setHouseholdId(householdId);
532	        for (Owner existing : household) {
533	            if (existing.getHouseholdId() == null || existing.getHouseholdId().isBlank()) {
534	                existing.setHouseholdId(householdId);
535	                ownerRepository.save(existing);
536	            }
537	        }
538	    }
539	
540	    /**
541	     * Stamps {@code owner} with the number of owners sharing its {@code householdId} (see {@link
542	     * Owner#getHouseholdSize()}), so presentation code can derive the membership tier without
543	     * reaching into the data store. A {@code null} owner or one without a household id is left at
544	     * size 0.
545	     */
546	    private void populateHouseholdSize(Owner owner) {
547	        if (owner == null) {
548	            return;
549	        }
550	        String householdId = owner.getHouseholdId();
551	        if (householdId == null || householdId.isBlank()) {
552	            owner.setHouseholdSize(0);
553	            return;
554	        }
555	        int count = 0;
556	        for (Owner existing : ownerRepository.findAll()) {
557	            if (householdId.equals(existing.getHouseholdId())) {
558	                count++;
559	            }
560	        }
561	        owner.setHouseholdSize(count);
562	    }
563	
564	    /**
565	     * Stamps every owner in {@code owners} with its household size in a single pass over the data
566	     * store, so a list/page of owners is counted without a per-owner query.
567	     *
568	     * @see #populateHouseholdSize(Owner)
569	     */
570	    private void populateHouseholdSizes(Collection<Owner> owners) {
571	        if (owners.isEmpty()) {
572	            return;
573	        }
574	        Map<String, Integer> sizes = new HashMap<>();
575	        for (Owner existing : ownerRepository.findAll()) {
576	            String householdId = existing.getHouseholdId();
577	            if (householdId != null && !householdId.isBlank()) {
578	                sizes.merge(householdId, 1, Integer::sum);
579	            }
580	        }
581	        for (Owner owner : owners) {
582	            String householdId = owner.getHouseholdId();
583	            owner.setHouseholdSize(householdId == null ? 0 : sizes.getOrDefault(householdId, 0));
584	        }
585	    }
586	
587	    /**
588	     * Returns the {@code householdId} shared by a household: the first non-blank identifier already
589	     * carried by an existing member, or otherwise a freshly derived stable identifier for the
590	     * joining {@code owner}'s normalized lastName and address.
591	     */
592	    private String resolveHouseholdId(Owner owner, List<Owner> household) {
593	        for (Owner existing : household) {
594	            if (existing.getHouseholdId() != null && !existing.getHouseholdId().isBlank()) {
595	                return existing.getHouseholdId();
596	            }
597	        }
598	        return generateHouseholdId(normalizeHouseholdValue(owner.getLastName()),
599	            normalizeHouseholdAddress(owner.getAddress()));
600	    }
601	
602	    /**
603	     * Derives a stable {@code householdId} formatted {@code 'HH-<12 upper-hex>'} from the SHA-256
604	     * digest of the normalized {@code lastName} and {@code address}, so all owners in the same
605	     * household deterministically share the same identifier.
606	     */
607	    private static String generateHouseholdId(String lastName, String address) {
608	        try {
609	            MessageDigest digest = MessageDigest.getInstance("SHA-256");
610	            byte[] hash = digest.digest((lastName + "\u0000" + address).getBytes(StandardCharsets.UTF_8));
611	            StringBuilder sb = new StringBuilder();
612	            for (int i = 0; i < 6; i++) {
613	                sb.append(String.format("%02X", hash[i]));
614	            }
615	            return "HH-" + sb;
616	        } catch (NoSuchAlgorithmException e) {
617	            throw new IllegalStateException("SHA-256 not available", e);
618	        }
619	    }
620	
621	    /**
622	     * Normalizes a household comparison value by trimming, collapsing runs of whitespace into a
623	     * single space and lower-casing, so comparisons ignore case and incidental whitespace.
624	     */
625	    private static String normalizeHouseholdValue(String value) {
626	        if (value == null) {
627	            return "";
628	        }
629	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
630	    }
631	
632	    /**
633	     * Household comparison value for an address: the canonical {@link #normalizeAddress(String)}
634	     * form (never {@code null}), so duplicate detection and the shared household id compare
635	     * addresses using the same normalized representation that is stored and returned.
636	     */
637	    private static String normalizeHouseholdAddress(String address) {
638	        String normalized = normalizeAddress(address);
639	        return normalized == null ? "" : normalized;
640	    }
641	
642	    @Override
643	    @Transactional(readOnly = true)
644	    public Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException {
645	        Collection<Owner> owners = ownerRepository.findByLastName(lastName);
646	        populateHouseholdSizes(owners);
647	        return owners;
648	    }
649	
650	    @Override
651	    @Transactional(readOnly = true)
652	    public Collection<Visit> findVisitsByPetId(int petId) {
653	        return visitRepository.findByPetId(petId);
654	    }
655	
656	    @Override
657	    @Transactional(readOnly = true)
658	    public List<Specialty> findSpecialtiesByNameIn(Set<String> names) {
659	        return findEntityById(() -> specialtyRepository.findSpecialtiesByNameIn(names));
660	    }
661	
662	    private <T> T findEntityById(Supplier<T> supplier) {
663	        try {
664	            return supplier.get();
665	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
666	            // Just ignore not found exceptions for Jdbc/Jpa realization
667	            return null;
668	        }
669	    }
670	
671	}
